def get_path(start, target, walls, boxes):
    queue = collections.deque([(start, "")])
    visited = {start}
    while queue:
        (r, c), path = queue.popleft()
        if (r, c) == target:
            return path
        for dr, dc, m in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
            nr, nc = r + dr, c + dc
            if (nr, nc) not in walls and (nr, nc) not in boxes and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append(((nr, nc), path + m))
    return None

def move_box(box_start, box_target, player_start, walls, boxes):
    queue = collections.deque([(box_start, player_start, "")])
    visited = {(box_start, player_start)}
    while queue:
        b, p, path = queue.popleft()
        if b == box_target:
            return b, p, path
        for dr, dc, m in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
            player_goal = (b[0] - dr, b[1] - dc)
            if player_goal not in walls and (player_goal not in boxes or player_goal == b):
